function clearRunArtifacts()
%CLEARRUNARTIFACTS Remove files and figures generated by FPF.RUN.

    packageDirectory = fileparts(mfilename("fullpath"));
    artifactNames = ["CommandWindow_output.txt",...
        "FIR_filter_response_comparison.fig",...
        "FIR_filter_response_comparison.pdf",...
        "FIR_filter_response_comparison.png",...
        "output_data.mat"];
    for artifactName = artifactNames
        artifactPath = fullfile(packageDirectory,artifactName);
        if isfile(artifactPath)
            delete(artifactPath);
        end
    end

    figureHandles = findall(groot,"Type","figure",...
        "Name","Squared transmission response comparison");
    if ~isempty(figureHandles)
        close(figureHandles);
    end
end
